CREATE TABLE IF NOT EXISTS leave_type (id CHAR(36) PRIMARY KEY, code VARCHAR(32) NOT NULL, name VARCHAR(120) NOT NULL, counting VARCHAR(16) NOT NULL, approval_target VARCHAR(16) NOT NULL, attachment_required_from_days DECIMAL(5,1) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY leave_type_code_unique (code), UNIQUE KEY leave_type_name_unique (name)) DEFAULT CHARSET=utf8mb4;
