CREATE TABLE IF NOT EXISTS leave_entitlement (employment_type_id CHAR(36) NOT NULL, leave_type_id CHAR(36) NOT NULL, days_per_year DECIMAL(5,1) NOT NULL, first_year_days DECIMAL(5,1) NULL, max_accumulated_days DECIMAL(5,1) NULL, max_accumulated_days_after_10_years DECIMAL(5,1) NULL, min_service_months INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, PRIMARY KEY (employment_type_id, leave_type_id), KEY leave_entitlement_leave_type_index (leave_type_id), CONSTRAINT leave_entitlement_employment_type_fk FOREIGN KEY (employment_type_id) REFERENCES hr_employment_type(id), CONSTRAINT leave_entitlement_leave_type_fk FOREIGN KEY (leave_type_id) REFERENCES leave_type(id)) DEFAULT CHARSET=utf8mb4;
