CREATE TABLE IF NOT EXISTS leave_holiday (holiday_date DATE PRIMARY KEY, name VARCHAR(120) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS leave_setting (id TINYINT PRIMARY KEY, min_working_days_per_month INT NOT NULL DEFAULT 15, updated_at DATETIME NOT NULL) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO leave_setting (id, min_working_days_per_month, updated_at) VALUES (1, 15, UTC_TIMESTAMP());
CREATE TABLE IF NOT EXISTS leave_request (request_id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, leave_type_id CHAR(36) NOT NULL, fiscal_year INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, start_half VARCHAR(16) NOT NULL, end_half VARCHAR(16) NOT NULL, days DECIMAL(5,1) NOT NULL, reason VARCHAR(1000) NOT NULL, contact_during_leave VARCHAR(500) NULL, attachment_id CHAR(36) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY leave_request_person_year_index (person_id, fiscal_year), KEY leave_request_person_start_index (person_id, start_date), KEY leave_request_leave_type_index (leave_type_id), CONSTRAINT leave_request_request_fk FOREIGN KEY (request_id) REFERENCES request(id), CONSTRAINT leave_request_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT leave_request_leave_type_fk FOREIGN KEY (leave_type_id) REFERENCES leave_type(id), CONSTRAINT leave_request_attachment_fk FOREIGN KEY (attachment_id) REFERENCES attachment(id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS leave_cancellation (request_id CHAR(36) PRIMARY KEY, leave_request_id CHAR(36) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, start_half VARCHAR(16) NOT NULL, end_half VARCHAR(16) NOT NULL, days DECIMAL(5,1) NOT NULL, created_at DATETIME NOT NULL, KEY leave_cancellation_leave_request_index (leave_request_id), CONSTRAINT leave_cancellation_request_fk FOREIGN KEY (request_id) REFERENCES request(id), CONSTRAINT leave_cancellation_leave_request_fk FOREIGN KEY (leave_request_id) REFERENCES leave_request(request_id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS leave_opening_balance (person_id CHAR(36) NOT NULL, fiscal_year INT NOT NULL, leave_type_id CHAR(36) NOT NULL, carried_days DECIMAL(5,1) NOT NULL DEFAULT 0, used_days DECIMAL(5,1) NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, PRIMARY KEY (person_id, fiscal_year, leave_type_id), KEY leave_opening_balance_leave_type_index (leave_type_id), CONSTRAINT leave_opening_balance_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT leave_opening_balance_leave_type_fk FOREIGN KEY (leave_type_id) REFERENCES leave_type(id)) DEFAULT CHARSET=utf8mb4;
